import heapq

def match(orders):
    trades = []
    buy_heap = []  # max-heap by price (stored as -price), then by arrival time
    sell_heap = []  # min-heap by price, then by arrival time
    book = {}  # id -> dict with side, price, qty, arrival, active
    counter = 0

    def add_to_book(oid, side, price, qty, arrival):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, oid))
        else:
            heapq.heappush(sell_heap, (price, arrival, oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        arrival = counter
        counter += 1
        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_arrival, top_id = heap[0]
            else:
                neg_price, top_arrival, top_id = heap[0]
                top_price = -neg_price

            resting = book.get(top_id)
            if resting is None or not resting['active'] or resting['qty'] <= 0:
                heapq.heappop(heap)
                continue

            # check price condition (market orders have no price limit)
            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, resting['qty'])
            trade_price = top_price

            if side == 'buy':
                trades.append([oid, top_id, trade_price, trade_qty])
            else:
                trades.append([top_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                heapq.heappop(heap)
                resting['active'] = False
            # else: partial fill, stays in heap with reduced qty tracked in book

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, arrival)
        # ioc and market: any remainder is discarded (do nothing)

    return trades

